function validate([s]) {
  if (!Array.isArray(s) || s.length < 1 || s.length > 99) return 's needs 1 to 99 tokens.';
  if (s.length % 2 === 0) return 's must have an odd number of tokens.';
  const stack = [];
  for (const token of s) {
    if (typeof token !== 'string') return 'Every token is a string.';
    if (token === '+' || token === '-' || token === '*' || token === '/') {
      if (stack.length < 2) return 's must be a valid postfix expression.';
      const b = stack.pop();
      const a = stack.pop();
      if (token === '/' && b === 0) return 'The expression must not divide by zero.';
      const value = token === '+' ? a + b : token === '-' ? a - b : token === '*' ? a * b : Math.trunc(a / b);
      if (Math.abs(value) > 1000000000) return 'Every intermediate value must stay within 10^9 in absolute value.';
      stack.push(value);
    } else {
      if (!/^\d+$/.test(token) || Number(token) > 100000) return 'Numbers are whole numbers from 0 to 10^5.';
      stack.push(Number(token));
    }
  }
  if (stack.length !== 1) return 's must be a valid postfix expression.';
  return null;
}

