function adapt(input, solve, kit) {
  const [s] = input;
  const root = solve(s.slice());
  if (!root || typeof root.evaluate !== 'function') throw new Error('Return the root node: an object with an evaluate() method.');
  const value = root.evaluate();
  if (typeof value !== 'number') throw new Error('evaluate() must return a number.');
  return value;
}

