function buildTree(s) {
  const operations = {
    '+': (a, b) => a + b,
    '-': (a, b) => a - b,
    '*': (a, b) => a * b,
    '/': (a, b) => Math.trunc(a / b),
  };
  class NumberNode {
    constructor(value) {
      this.value = value;
    }
    evaluate() {
      return this.value;
    }
  }
  class OperatorNode {
    constructor(operator, left, right) {
      this.operator = operator;
      this.left = left;
      this.right = right;
    }
    evaluate() {
      const leftValue = this.left.evaluate();
      const rightValue = this.right.evaluate();
      return operations[this.operator](leftValue, rightValue);
    }
  }
  const stack = [];
  for (const token of s) {
    if (token in operations) {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(new OperatorNode(token, left, right));
    } else {
      stack.push(new NumberNode(Number(token)));
    }
  }
  return stack.pop();
}

