function buildTree(s) {
  // No tree at all: repeatedly collapse the first operator with the two numbers just before it.
  const tokens = s.map(token => ('+-*/'.includes(token) ? token : Number(token)));
  while (tokens.length > 1) {
    const i = tokens.findIndex(token => typeof token === 'string');
    const a = tokens[i - 2];
    const b = tokens[i - 1];
    let value;
    if (tokens[i] === '+') value = a + b;
    else if (tokens[i] === '-') value = a - b;
    else if (tokens[i] === '*') value = a * b;
    else value = (a - (a % b)) / b;
    tokens.splice(i - 2, 3, value);
  }
  const result = tokens[0];
  return { evaluate: () => result };
}

