function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const operatorCount = size === 'large' ? 40 + pick(10) : pick(7);
  const bigNumbers = size === 'large' || rand() < 0.3;
  const pushBias = 0.3 + rand() * 0.5;
  const number = () => {
    const r = rand();
    if (r < 0.12) return 0;
    if (bigNumbers && r < 0.3) return pick(100001);
    return 1 + pick(size === 'large' ? 30 : 12);
  };
  const tokens = [];
  const stack = [];
  let numbersLeft = operatorCount + 1;
  let operatorsLeft = operatorCount;
  while (numbersLeft > 0 || operatorsLeft > 0) {
    const canApply = stack.length >= 2 && operatorsLeft > 0;
    if (numbersLeft > 0 && (!canApply || rand() < pushBias)) {
      const value = number();
      tokens.push(String(value));
      stack.push(value);
      numbersLeft--;
      continue;
    }
    // Only choose operators that keep the value in range and never divide by zero.
    const b = stack.pop();
    const a = stack.pop();
    const options = [];
    if (Math.abs(a + b) <= 1000000000) options.push('+');
    if (Math.abs(a - b) <= 1000000000) options.push('-');
    if (Math.abs(a * b) <= 1000000000) options.push('*');
    if (b !== 0) options.push('/');
    const op = options[pick(options.length)];
    tokens.push(op);
    stack.push(op === '+' ? a + b : op === '-' ? a - b : op === '*' ? a * b : Math.trunc(a / b));
    operatorsLeft--;
  }
  return [tokens];
}
